local ship = require("ship")
local read_actor = require("examples.read_actor")
local numbers = require("examples.damage_numbers")
local progress = require("examples.progress")

local function observed(category, health, maximum)
    local handle = mock.actors.observe {
        actor_id = 0x13, category = category, params = 7,
        health = health, max_health = maximum or health,
    }
    return handle, { handle = handle, actor_id = 0x13, category = category, params = 7 }
end

describe("guia da RFC 0031", function()
    it("carrega os exemplos e reutiliza módulos do pacote", function()
        assert.is_true(ship.capabilities.has("core.modules"))
        local settings = require("examples.settings")
        assert.equals("actors-guide", settings.label)
        assert.equals(settings, require("examples.modules"))
        settings.changed = true
        assert.is_true(require("examples.settings").changed)
        assert.is_false(pcall(require, "../outside"))
        assert.is_false(pcall(require, "examples.missing"))
    end)

    it("lê a instância e dobra a vida de cada inimigo no init", function()
        local handle, actor = observed(5, 4)
        local second = observed(5, 4)
        assert.equals(1, mock.events.emit("actor.init", { actor = actor }))
        local data, err = read_actor(handle)
        assert.is_nil(err)
        assert.equals(8, data.health)
        assert.equals(8, data.max_health)
        assert.is_true(ship.actor.get(handle, "extended"))
        assert.equals(4, ship.actor.get(second, "health"))
        assert.equals(7, ship.actor.get(handle, "params"))
        assert.is_nil(data.screen_x)
        assert.is_nil(data.screen_y)
    end)

    it("preserva a fração ferida e limita o máximo", function()
        local handle, actor = observed(5, 1, 4)
        mock.events.emit("actor.init", { actor = actor })
        assert.equals(2, ship.actor.get(handle, "health"))
        assert.equals(8, ship.actor.get(handle, "max_health"))
        -- Valor sintético para o corte; não representa vida vanilla u8.
        local large, large_actor = observed(5, 40000)
        mock.events.emit("actor.init", { actor = large_actor })
        assert.equals(65535, ship.actor.get(large, "max_health"))
    end)

    it("deixa jogador, chefe, NPC e ator sem vida intactos", function()
        for _, category in ipairs({ 2, 9, 4 }) do
            local handle, actor = observed(category, 4)
            mock.events.emit("actor.init", { actor = actor })
            assert.is_false(ship.actor.get(handle, "extended"))
            assert.equals(4, ship.actor.get(handle, "max_health"))
        end
        local handle, actor = observed(5, 0)
        mock.events.emit("actor.init", { actor = actor })
        assert.is_false(ship.actor.get(handle, "extended"))
    end)

    it("distingue handle expirado de erro de argumento", function()
        local handle = observed(5, 4)
        -- O mock não emite destroy automaticamente nem simula a cena.
        mock.events.emit("actor.destroy", { handle = handle })
        assert.equals(4, ship.actor.get(handle, "health"))
        assert.is_true(mock.actors.destroy(handle))
        local value, err = read_actor(handle)
        assert.is_nil(value)
        assert.is_nil(err)
        assert.is_false(ship.actor.set_max_health(handle, 8))
        value, err = ship.actor.get({}, "health")
        assert.is_nil(value)
        assert.equals("invalid_argument", err.code)
        local live = observed(5, 4)
        value, err = ship.actor.get(live, "hp")
        assert.is_nil(value)
        assert.equals("invalid_argument", err.code)
        value, err = ship.actor.set_max_health(live, 8.0)
        assert.is_nil(value)
        assert.equals("invalid_argument", err.code)
    end)

    it("coleta o dano confirmado sem multiplicar a proposta", function()
        local handle, actor = observed(5, 4)
        mock.events.emit("actor.init", { actor = actor })
        local before = #numbers
        -- A emissão sintética não aplica dano nem atualiza o provider.
        mock.events.emit("hook.oot.actor.damaged", {
            target = actor, amount = 3, health = 5, max_health = 8, extended = true,
        })
        assert.equals(before + 1, #numbers)
        local number = numbers[#numbers]
        assert.equals(3, number.amount)
        assert.equals(5, number.health)
        assert.equals(8, number.max_health)
        assert.is_true(number.extended)
        assert.is_nil(number.x)
        assert.is_nil(number.y)
        assert.equals(8, ship.actor.get(handle, "health"))
        mock.events.emit("hook.oot.actor.damaged", {
            target = actor, amount = 0, health = 5, max_health = 8, extended = true,
        })
        assert.equals(before + 1, #numbers)
        mock.actors.destroy(handle)
        assert.equals(3, number.amount)
    end)

    it("separa XP por arquivo e opções globais do mod", function()
        mock.save.unload()
        assert.is_false(progress.add_xp(10))
        local value, err = ship.save.get("xp", 0)
        assert.is_nil(value)
        assert.equals("invalid_state", err.code)
        assert.is_true(progress.show_numbers())
        assert.is_true(progress.set_show_numbers(false))
        mock.save.load(0)
        assert.is_true(progress.add_xp(10))
        assert.is_true(progress.add_xp(7))
        assert.equals(17, ship.save.get("xp"))
        mock.save.load(1)
        assert.equals(0, ship.save.get("xp", 0))
        assert.is_false(progress.show_numbers())
        assert.is_true(progress.add_xp(3))
        mock.save.load(0)
        assert.equals(17, ship.save.get("xp"))
        assert.is_true(ship.save.set("flag", false))
        assert.is_false(ship.save.get("flag", true))
        assert.is_true(ship.save.set("label", "arquivo zero"))
        assert.equals("arquivo zero", ship.save.get("label"))
        assert.is_true(ship.save.delete("label"))
        assert.is_false(ship.save.delete("label"))
        mock.save.unload()
        value, err = ship.save.set("xp", 99)
        assert.is_nil(value)
        assert.equals("invalid_state", err.code)
        value, err = ship.save.delete("xp")
        assert.is_nil(value)
        assert.equals("invalid_state", err.code)
        mock.save.load(1)
        assert.equals(3, ship.save.get("xp"))
    end)
end)
